mapper.select:
SELECT a.id, a.person_id, a.user_name, a.nick_name, a.avatar, a.mobile, a.email, a.password, a.pwd_reset_required, a.status, a.del_flag, a.create_by, a.create_time, a.update_by, a.update_time, p.real_name AS person_name FROM sys_account a LEFT JOIN md_person p ON a.person_id = p.id
AND a.user_name like #{userName}
ORDER BY a.create_time DESC

SELECT a.id, a.person_id, a.user_name, a.nick_name, a.avatar, a.mobile, a.email, a.password, a.pwd_reset_required, a.status, a.del_flag, a.create_by, a.create_time, a.update_by, a.update_time, p.real_name AS person_name FROM sys_account a LEFT JOIN md_person p ON a.person_id = p.id
AND a.status = #{sysAccountView.status}
AND a.del_flag = #{sysAccountView.delFlag}
ORDER BY a.create_time DESC

SELECT a.id, a.user_name FROM sys_account a
a.id != #{sysAccountView.id}
AND a.user_name = #{sysAccountView.userName}
